function generate(rand, size) {
  const span = size === 'large' ? 1000 : 20;
  const make = () => {
    const n = size === 'large' ? 500 : 3 + Math.floor(rand() * 8);
    return [Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span), Math.floor(rand() * (6 * span + 1)) - 3 * span];
  };
  // The problem guarantees one closest total, so small inputs retry until it is unique.
  for (;;) {
    const [nums, target] = make();
    if (size === 'large') return [nums, target];
    const gaps = new Map();
    for (let i = 0; i < nums.length; i++) for (let j = i + 1; j < nums.length; j++) for (let k = j + 1; k < nums.length; k++) { const sum = nums[i] + nums[j] + nums[k]; gaps.set(sum, Math.abs(sum - target)); }
    const least = Math.min(...gaps.values());
    if ([...gaps.values()].filter(g => g === least).length === 1) return [nums, target];
  }
}

